// Browser interface for the small Node + SQLite booking server.
const $ = (selector, root=document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((cents||0)/100);
function notice(el,message,kind='info'){if(el){el.textContent=message;el.className=`notice ${kind}`}}
function renderFileLinks(files,kind,title){const matches=(files||[]).filter(file=>file.kind===kind);return matches.length?`<div class="uploaded-files"><b>${esc(title)}</b><ul>${matches.map(file=>`<li><a href="/api/files/${encodeURIComponent(file.id)}" target="_blank" rel="noopener">${esc(file.original_name)}</a></li>`).join('')}</ul></div>`:''}
async function api(url,options={}){
  const response=await fetch(url,{...options,credentials:'same-origin',headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});
  const raw=await response.text();let body;try{body=JSON.parse(raw)}catch{const html=/^\s*(?:<!doctype\s+html|<html|<!doctype)/i.test(raw);throw new Error(html?`The deployed site returned an HTML page for ${url} (HTTP ${response.status}) instead of the booking API. Deploy and start the Node.js app with “npm start” on Node 22.5 or newer; a static-only host cannot handle sign-in.`:`The server returned an unexpected response for ${url} (HTTP ${response.status}). Check that the Node.js server is running and review the hosting logs.`)}
  if(!response.ok)throw new Error(body.error||'Something went wrong. Please try again.');return body;
}
function fileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error(`Could not read ${file.name}.`));reader.readAsDataURL(file)})}
function setupHeader(user){const host=$('#portal-header');if(!host)return;host.innerHTML=`<div class="portal-top"><a class="logo" href="index.html"><div><div class="logo-mark">CLEAN <span class="diamonds">◆ ◆ ◆</span></div><small>Professional Cleaning Service</small></div></a><nav aria-label="Main navigation"><a href="index.html">Home</a><a href="residential.html">Services</a><a href="account.html">My bookings</a><a href="account.html">Request a quote</a><a href="https://wa.me/19178255246">WhatsApp</a><span>${esc(user?.email||'')}</span>${user?'<button class="btn outline" id="signout">Sign out</button>':'<a href="signup.html">Create account</a><a class="btn outline" href="login.html">Sign in</a>'}</nav></div>`;$('#signout')?.addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}finally{location.href='index.html'}})}
function showFileWarning(){if(location.protocol==='file:'){const n=$('#config-note');notice(n,'You opened this page directly. Booking accounts work when you start the website using the included start command, or visit its deployed website address.','warn');document.querySelectorAll('form button[type="submit"]').forEach(x=>x.disabled=true)}}
function localDateMinimum(){const input=$('[name="requested_date"]');if(input){const date=new Date();input.min=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,10)}}

async function authPage(){setupHeader(null);showFileWarning();if(location.protocol==='file:')return;const page=document.body.dataset.portal;let currentUser=null;try{({user:currentUser}=await api('/api/me'))}catch{}if(currentUser){const next=new URLSearchParams(location.search).get('next');location.href=next==='admin.html'&&currentUser.role==='admin'?'admin.html':'account.html';return}const message=$('#auth-message');
  $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));notice(message,'Signing in…');try{const {user}=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});const next=new URLSearchParams(location.search).get('next');location.href=next==='admin.html'&&user.role==='admin'?'admin.html':'account.html'}catch(error){notice(message,error.message,'error')}});
  $('#signup-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));notice(message,'Creating your account…');try{await api('/api/auth/signup',{method:'POST',body:JSON.stringify(data)});location.href='account.html'}catch(error){notice(message,error.message,'error')}});
}

async function accountPage(){showFileWarning();if(location.protocol==='file:')return;let user;try{({user}=await api('/api/me'))}catch{location.href='login.html?next=account.html';return}setupHeader(user);localDateMinimum();const accountName=$('#account-name');if(accountName)accountName.textContent=user.name;
  $('#booking-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),data=Object.fromEntries(f),photoFiles=f.getAll('photos').filter(file=>file instanceof File&&file.size>0);if(!photoFiles.length){notice($('#booking-message'),'Please upload at least one photo of the space.','error');return}if(photoFiles.length>5||photoFiles.reduce((n,file)=>n+file.size,0)>15*1024*1024){notice($('#booking-message'),'Choose up to five photos with a combined size under 15 MB.','error');return}data.preferred_date=data.requested_date;delete data.requested_date;delete data.photos;data.add_ons=f.getAll('add_ons');notice($('#booking-message'),'Uploading photos and sending your booking request…');try{data.photos=await Promise.all(photoFiles.map(async file=>({name:file.name,type:file.type,data:await fileAsDataUrl(file)})));await api('/api/bookings',{method:'POST',body:JSON.stringify(data)});form.reset();localDateMinimum();notice($('#booking-message'),'Photos received. Your quote status is waiting for review. Lesa will update you within 24–48 hours.','success');await loadBookings()}catch(error){notice($('#booking-message'),error.message,'error')}});
  await loadBookings();
  async function loadBookings(){try{const {bookings}=await api('/api/bookings');const list=$('#booking-list');if(!bookings.length){list.innerHTML='<div class="portal-card"><p>No quote requests yet. Upload photos and send a request above. We’ll update your quote within 24–48 hours.</p></div>';return}list.innerHTML=bookings.map(b=>`<article class="portal-card booking-item"><div class="booking-head"><div><div class="eyebrow">${esc(b.service_type)} · ${esc(b.package_name)} Clean</div><h3>Request ${esc(b.id.slice(0,8).toUpperCase())}</h3><p>${esc(b.city)}, ${esc(b.zip_code)} · ${esc(b.frequency)} · ${esc(b.preferred_date||'Date to be arranged')} · ${esc(b.preferred_window)}</p></div><span class="status-pill">${esc(b.payment_status==='confirmed'?'payment confirmed':b.payment_status==='submitted'?'payment proof submitted':b.status.replace('_',' '))}</span></div>${b.add_ons.length?`<p><b>Add-ons:</b> ${b.add_ons.map(esc).join(', ')}</p>`:''}${renderFileLinks(b.files,'booking_photo','Your uploaded space photos')}<p>${esc(b.admin_message||(b.payment_status==='confirmed'?'Payment received. Lesa will contact you to arrange the cleaning.':b.payment_status==='submitted'?'Payment proof submitted. Lesa will contact you after confirming the payment.':b.quote_amount_cents?'Your quote is ready. Follow the Zelle payment instructions below.':'Quote status: waiting for review. Lesa will update you within 24–48 hours.'))}</p>${b.files?.some(file=>file.kind==='booking_photo')?`<p class="muted small">${b.files.filter(file=>file.kind==='booking_photo').length} space photo(s) uploaded</p>`:''}${b.quote_amount_cents?`<div class="payment-box"><div class="eyebrow">${b.payment_status==='confirmed'?'Zelle payment confirmed':b.payment_status==='submitted'?'Payment screenshot received':'Quote ready · Pay with Zelle'}</div><strong class="quote-total">${money(b.quote_amount_cents)}</strong><p>Send exactly ${money(b.quote_amount_cents)} with Zelle to: <b>${esc(b.zelle_recipient)}</b></p><p>Open your bank app and select Zelle. Double-check the recipient before paying.</p>${b.payment_status==='requested'?`<div class="pay-actions"><button class="btn outline copy-payment" data-copy="${esc(b.zelle_recipient)}">Copy Zelle recipient</button><label class="field">Upload payment screenshot (required)<input class="payment-proof" type="file" accept="image/jpeg,image/png,image/webp,image/gif" required></label><label class="field">Payment reference (optional)<input class="payment-ref" placeholder="Confirmation or memo reference"></label><button class="btn submitted" data-id="${esc(b.id)}">Submit Zelle payment proof</button></div>`:b.payment_status==='submitted'?`<p class="notice warn">Your screenshot is with Lesa for review. After she confirms the Zelle payment, she’ll contact you to arrange the cleaning.</p>${renderFileLinks(b.files,'payment_proof','Your payment screenshot')}`:b.payment_status==='confirmed'?'<p class="notice success">Payment received and confirmed. Lesa will contact you to arrange your cleaning.</p>':''}</div>`:'<p class="muted">Quote pending. We’ll update your price and payment instructions here within 24–48 hours.</p>'}<p class="muted small">Submitted ${new Date(b.created_at+'Z').toLocaleString()}</p></article>`).join('');
      list.querySelectorAll('.copy-payment').forEach(btn=>btn.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(btn.dataset.copy);btn.textContent='Copied'}catch{btn.textContent=btn.dataset.copy}}));list.querySelectorAll('.submitted').forEach(btn=>btn.addEventListener('click',async()=>{const card=btn.closest('.booking-item'),reference=$('.payment-ref',card).value.trim(),file=$('.payment-proof',card).files[0];if(!file){notice($('.payment-box',card),'Upload a screenshot of your Zelle payment before submitting.','error');return}btn.disabled=true;try{const proof={name:file.name,type:file.type,data:await fileAsDataUrl(file)};await api(`/api/bookings/${btn.dataset.id}/payment-submitted`,{method:'POST',body:JSON.stringify({reference,payment_proof:proof})});await loadBookings()}catch(error){notice($('.payment-box',card),error.message,'error');btn.disabled=false}}));
    }catch(error){notice($('#booking-list'),error.message,'error')}}
}

async function adminPage(){
  showFileWarning();if(location.protocol==='file:')return;setupHeader(null);
  const loginPanel=$('#admin-login'),dashboard=$('#admin-dashboard'),loginMessage=$('#admin-login-message');
  async function enterDashboard(user){if(user.role!=='admin'){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}notice(loginMessage,'That account is not an administrator. Use the admin email and password shown when the server was first started.','error');return}setupHeader(user);loginPanel.hidden=true;dashboard.hidden=false;await renderBookings();$('#refresh-admin')?.addEventListener('click',renderBookings)}
  try{const {user}=await api('/api/me');if(user.role==='admin')await enterDashboard(user);else notice(loginMessage,'Sign in here with the administrator account. Your customer account does not have admin access.','warn')}catch{}
  $('#admin-login-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));notice(loginMessage,'Signing in…');try{const {user}=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});await enterDashboard(user)}catch(error){notice(loginMessage,error.message,'error')}});
  async function renderBookings(){await renderCustomerBookings()}
  async function renderCustomerBookings(){const host=$('#admin-content');notice(host,'Loading bookings…');try{const {bookings}=await api('/api/bookings');if(!bookings.length){host.innerHTML='<div class="portal-card">No account bookings yet.</div>';return}host.innerHTML=bookings.map(b=>`<article class="portal-card admin-booking"><div class="booking-head"><div><div class="eyebrow">${esc(b.service_type)} · ${esc(b.package_name)} · ${esc(b.frequency)}</div><h3>${esc(b.customer_name)}</h3><p><a href="mailto:${esc(b.customer_email)}">${esc(b.customer_email)}</a> · <a href="tel:${esc(b.customer_phone)}">${esc(b.customer_phone)}</a></p><p>${esc(b.address)}, ${esc(b.city)} ${esc(b.zip_code)} · ${esc(b.preferred_date||'Flexible date')} · ${esc(b.preferred_window)} · ${new Date(b.created_at+'Z').toLocaleString()}</p></div><span class="status-pill">${esc(b.status.replace('_',' '))} · ${esc(b.payment_status.replace('_',' '))}</span></div>${renderFileLinks(b.files,'booking_photo','Customer photos')}${renderFileLinks(b.files,'payment_proof','Zelle payment screenshot')}${b.add_ons.length?`<p><b>Add-ons:</b> ${b.add_ons.map(esc).join(', ')}</p>`:''}<p>${esc(b.notes||'No extra notes')}</p>${b.payment_reference?`<p><b>Customer payment note:</b> ${esc(b.payment_reference)} · submitted ${esc(b.payment_submitted_at||'')}</p>`:''}<form class="admin-edit booking-edit" data-id="${esc(b.id)}"><label class="field">Booking status<select name="status">${['new','reviewing','quote_ready','scheduled','completed','declined'].map(x=>`<option ${b.status===x?'selected':''} value="${x}">${x.replace('_',' ')}</option>`).join('')}</select></label><label class="field">Quote amount (USD)<input name="quote_amount" type="number" min="1" step="0.01" value="${b.quote_amount_cents?b.quote_amount_cents/100:''}" placeholder="250.00"></label><label class="field">Zelle email or US phone<input name="zelle_recipient" value="${esc(b.zelle_recipient)}" placeholder="Your enrolled Zelle email or phone"></label><label class="field">Payment status<select name="payment_status">${['not_paid','requested','submitted','confirmed'].map(x=>`<option ${b.payment_status===x?'selected':''} value="${x}">${x.replace('_',' ')}</option>`).join('')}</select></label><label class="field field-wide">Message to customer<textarea name="admin_message">${esc(b.admin_message)}</textarea></label><button class="btn" type="submit">Save booking & payment update</button><span class="notice" role="status"></span></form></article>`).join('');
    host.querySelectorAll('.booking-edit').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));if(data.payment_status==='not_paid'&&data.quote_amount)data.payment_status='requested';if(data.payment_status==='requested'&&data.status==='new')data.status='quote_ready';const button=$('button[type="submit"]',form);button.disabled=true;try{await api(`/api/admin/bookings/${form.dataset.id}`,{method:'PATCH',body:JSON.stringify(data)});notice($('.notice',form),'Saved. The customer can see this update in their account.','success');await renderBookings()}catch(error){notice($('.notice',form),error.message,'error');button.disabled=false}}));
    }catch(error){notice(host,error.message,'error')}}
  $('#admin-password-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));if(data.password!==data.confirm){notice($('#password-message'),'Those passwords do not match.','error');return}try{await api('/api/auth/password',{method:'POST',body:JSON.stringify({password:data.password})});notice($('#password-message'),'Password changed. Sign in again with your new password.','success');setTimeout(async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});location.href='admin.html'},1000)}catch(error){notice($('#password-message'),error.message,'error')}})
}

const page=document.body.dataset.portal;if(page==='auth'||page==='login'||page==='signup')authPage();else if(page==='account')accountPage();else if(page==='admin')adminPage();

